 55|   /** Report for the Monday-to-Sunday week containing `date`. */
 56|   weekly(date: unknown): WeeklyReport {
 57|     if (!validDate(date)) throw new DomainError(400, "date must be YYYY-MM-DD");
 58|     const t = new Date(`${date}T00:00:00Z`);
 59|     const monday = new Date(t.getTime() - ((t.getUTCDay() + 6) % 7) * DAY_MS);
 60|     const sunday = new Date(monday.getTime() + 6 * DAY_MS);
 61|     return this.range(monday.toISOString().slice(0, 10), sunday.toISOString().slice(0, 10));
 62|   }
 63| 
 64|   /** Report for an arbitrary inclusive date range (e.g. a whole season). */
 65|   range(from: unknown, to: unknown): WeeklyReport {
 66|     if (!validDate(from) || !validDate(to)) throw new DomainError(400, "from and to must be YYYY-MM-DD");
 67|     if (from > to) throw new DomainError(400, "from must not be after to");
 68| 
 69|     const totals: WeeklyReport["totals"] = {
 70|       sessions: 0, ticketsSold: 0, membersAdmitted: 0, occupancy: 0, hireIncomeCents: {},
 71|       refundedBookings: 0, refundedCents: 0, sessionsOnHold: 0, sessionsCancelled: 0,
 72|     };
 73|     let capacity = 0;
 74|     const rows: SessionReportRow[] = [];
 75|     for (const s of this.sessions.findByDateRange(from, to)) {
 76|       const row: SessionReportRow = {
 77|         sessionId: s.id, date: s.date, start: s.start, end: s.end, status: s.status,
 78|         capacity: s.capacity, ticketsSold: 0, membersAdmitted: 0, occupancy: 0,
 79|         hireIncomeCents: {}, refundedBookings: 0, refundedCents: 0,
 80|       };
 81|       for (const b of this.bookings.findBySession(s.id)) {
 82|         if (b.status === "paid") {
 83|           if (b.membershipNumber) row.membersAdmitted += b.tickets;
 84|           else row.ticketsSold += b.tickets;
 85|           for (const [size, qty] of Object.entries(b.hire)) {
 86|             row.hireIncomeCents[size] = (row.hireIncomeCents[size] ?? 0) + qty * HIRE_PRICE_CENTS;
 87|           }
 88|         } else if (b.status === "refunded") {
 89|           row.refundedBookings++;
 90|           row.refundedCents += b.amountCents;
 91|         }
 92|       }
 93|       row.occupancy = s.capacity > 0 ? round((row.ticketsSold + row.membersAdmitted) / s.capacity) : 0;
 94|       rows.push(row);
 95| 
 96|       totals.sessions++;
 97|       capacity += s.capacity;
 98|       totals.ticketsSold += row.ticketsSold;
 99|       totals.membersAdmitted += row.membersAdmitted;
100|       totals.refundedBookings += row.refundedBookings;
101|       totals.refundedCents += row.refundedCents;
102|       for (const [size, c] of Object.entries(row.hireIncomeCents)) {
103|         totals.hireIncomeCents[size] = (totals.hireIncomeCents[size] ?? 0) + c;
104|       }
105|       if (s.status === "held") totals.sessionsOnHold++;
106|       if (s.status === "cancelled") totals.sessionsCancelled++;
107|     }
108|     totals.occupancy = capacity > 0 ? round((totals.ticketsSold + totals.membersAdmitted) / capacity) : 0;
109|     return { from, to, sessions: rows, totals };
110|   }
